import { phase } from '/tmp/probe/p.mjs';

const PRE = '<div class="codehilite"><pre><span></span><code>';
const POST = '</code></pre></div>';

// Run many snippets in ONE executable invocation by concatenating fenced blocks.
export function batch(cases, info = 'python') {
  const doc = cases.map(c => '```' + info + '\n' + c + '\n```').join('\n\n');
  const out = phase('e', doc);
  // split on div boundaries
  const parts = out.split('\n');
  // Each block is one line? no, may be multiline. Use regex over whole output.
  const re = /<div class="codehilite"><pre><span><\/span><code>([\s\S]*?)<\/code><\/pre><\/div>/g;
  const res = [];
  let m;
  while ((m = re.exec(out)) !== null) res.push(m[1]);
  return { raw: out, blocks: res };
}

export function one(code, info = 'python') {
  const out = phase('e', '```' + info + '\n' + code + '\n```');
  return out;
}

export { phase, PRE, POST };

