import { batch } from './drv.mjs';

// cases: array of [label, code]
export function report(cases, info='python', chunk=40) {
  for (let i = 0; i < cases.length; i += chunk) {
    const slice = cases.slice(i, i+chunk);
    const r = batch(slice.map(c=>c[1]), info);
    if (r.blocks.length !== slice.length) {
      console.log('!! MISMATCH blocks=' + r.blocks.length + ' cases=' + slice.length);
      console.log('RAW=' + JSON.stringify(r.raw));
    }
    slice.forEach((c, j) => {
      console.log('== ' + c[0]);
      console.log('IN  ' + JSON.stringify(c[1]));
      console.log('OUT ' + JSON.stringify(r.blocks[j]));
    });
  }
}

